bool StructTraits<::guest_view::mojom::SetSizeParams::DataView, ::guest_view::mojom::SetSizeParamsPtr>::Read(
    ::guest_view::mojom::SetSizeParams::DataView input,
    ::guest_view::mojom::SetSizeParamsPtr* output) {
  bool success = true;
  ::guest_view::mojom::SetSizeParamsPtr result(::guest_view::mojom::SetSizeParams::New());
  
      if (success)
        result->enable_auto_size = input.enable_auto_size();
      if (success && !input.ReadMin(&result->min))
        success = false;
      if (success && !input.ReadMax(&result->max))
        success = false;
  *output = std::move(result);
  return success;
}

