void PageHandlerAsyncWaiter::CreateGuest(
    ::base::DictValue create_params, int32_t* out_guest_instance_id) {
  base::RunLoop loop;
  proxy_->CreateGuest(
      std::move(create_params),
      base::BindOnce(
          [](base::RunLoop* loop,
             int32_t* out_guest_instance_id
,
             int32_t guest_instance_id) {*out_guest_instance_id = std::move(guest_instance_id);
            loop->Quit();
          },
          &loop,
          out_guest_instance_id));
  loop.Run();
}

